entries[241616] = { ["name"] = "Der Lorenboss", ["text"] = "80 ( 80)\n\"Das Besiegen des Lorenbosses kann Ausrüstung, Rezepte, Währung, Sammelgegenstände und Kuriositäten gewähren.\"" }
