entries[241632] = { ["name"] = "Heroische Wachsfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Ein liebevoll geschnitzter und vorsichtig geformter Wachsklumpen, den Skibbles nach Euch modelliert hat. Man erkennt, wie viel Arbeit sie hineingesteckt hat. Was man nicht erkennt, ist, wo das Gesicht sein soll.\"\nVerkaufspreis:" }
entries[241633] = { ["name"] = "Winzige Dekorakete", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn die kleine Kurbel gedreht wird, macht die Miniaturrakete ein leises, surrendes Geräusch und eine hölzerner Auspuffflamme beginnt sich sanft zu drehen. Eine einfache Darstellung eines kleinen Nerubers mit einer Strichfigur wurde in eine der Finnen der Rakete geritzt.\"\nVerkaufspreis:" }
entries[241635] = { ["name"] = "Lückenhaftes Quadrat aus Spinnenseide", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses kleine, schlecht gewobene Quadrat scheint Muster sowohl der Neruber als auch der Arathi darzustellen. Eure Initialen wurden grob in die Ecke genäht.\"\nVerkaufspreis:" }
entries[241636] = { ["name"] = "Sturmglas und Federhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Eine einzelne, stahlblaue Sturmkrähenfeder baumelt sanft zwischen zwei Fragmenten aus Sturmglas. Eine kleine, rostige, in Lorenhall gefertigte Schraube und Mutter dienen als Schnalle.\"\nVerkaufspreis:" }
