entries[241645] = { ["name"] = "Verderbtes seidengewebtes Wams", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nBrust Stoff\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n80 ( 80)\n\"Teufelsberührte Runen schmücken dieses einst stilvolle Wams der Hochgeborenen.\"" }
