entries[242491] = { ["name"] = "Flüstern von K'aresh", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+1.130 Ausdauer\nErhöht Eure Tempowertung um + 1.053.\nErhöht Eure Meisterschaftswertung um + 702.\n\"Obwohl nur einer seine geschwächten Worte hörte, erreichte seine Botschaft die Sterne.\"\nVerkaufspreis:" }
