entries[242493] = { ["name"] = "Sternerhellter Schutz", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n5616 Rüstung\n+289 Stärke\n+886 Intelligenz\n+1.004 Ausdauer\nErhöht Eure kritische Trefferwertung um + 266.\nErhöht Eure Meisterschaftswertung um + 157.\nHaltbarkeit 120 / 120\nSchließt Biokuppel Al'dani in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[242494] = { ["name"] = "Lilie des ewigen Geflechts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\nBenutzen: Entnehmt den Schicksalen jener um Euch eine Leihgabe und erhöht Eure Meisterschaft für 15 Sek. um 2901 . (1 Min, 30 Sek. Abklingzeit)\nSchließt Biokuppel Al'dani in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[242495] = { ["name"] = "Körperlose Warpklaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\nAnlegen: Eure Nahkampfangriffe haben eine Chance, das Echo eines Sphärenjägers zu verdichten, das mit Euch angreift und ( 1 * 38432 ) Arkanschaden verursacht, der auf Gegner in seiner Bahn aufgeteilt wird.\nSchließt Biokuppel Al'dani in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[242497] = { ["name"] = "Parapoden von Azhiccar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 604.\nAnlegen: Eure Schadenszauber haben eine Chance, Milben anzulocken, die sich an Eurem Ziel laben und ihm bis zu ( 3176 * 5) Schattenschaden im Verlauf von 5 Sek. zufügen. Satte Milben teilen ihr Mahl mit Euch, was Eure Intelligenz jeweils für 30 Sek. um 634 erhöht.\nSchließt Biokuppel Al'dani in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
