entries[242535] = { ["name"] = "Vermisste Importe", ["text"] = "Questgegenstand\n\"Eine Vielfalt von Gegenständen aus aller Welt.\"\nVerkaufspreis:" }
entries[242539] = { ["name"] = "Prophetischer Streitkolben des Großmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Medivh, auch \"Mitternachtshieb\" genannt, war dafür bekannt, das Spielbrett mit einem einzigen mächtigen Hieb dieser Waffe von allen Figuren und Mitspielern zu säubern.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242540] = { ["name"] = "Blauer Streitkolben des Großmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Eine angemessene Waffe für einen König.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242541] = { ["name"] = "Königlicher Streitkolben des Großmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Springer auf Kopf.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242542] = { ["name"] = "Weißer Streitkolben des Großmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Der Schwung dieses Streitkolben haut Verteidiger schlicht um.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242547] = { ["name"] = "Rissiger Schlüsselstein", ["text"] = "Questgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Triumphale Hörner und Siegesschreie lassen sich schwach aus dem Inneren vernehmen.\"" }
entries[242555] = { ["name"] = "Aschenbringer", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Vergeltungspaladin\n\"So geschah es, dass Mann und Waffe zu einer Einheit zu verschmelzen schienen. Der Name Aschenbringer wurde zu einer Legende. Er wurde nicht nur der furchterregenden Klinge zugeschrieben, sondern auch dem unerbittlichen Ritter, der sie führte.\"\nVerkaufspreis:" }
entries[242556] = { ["name"] = "Zwillingsklingen des Betrügers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigt Verwüstungsdämonenjäger\n\"Statuiert Exempel an jenen, die närrisch genug sind, sich Euch zu widersetzen, dann wird der Rest ihrer Art sich Euch zu Füßen werfen.\"\nVerkaufspreis:" }
entries[242557] = { ["name"] = "Zwillingsklingen des Betrügers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigt Verwüstungsdämonenjäger\n\"Das Ende ist gekommen! Lasst die Zerstörung dieser Welt beginnen!\"\nVerkaufspreis:" }
entries[242558] = { ["name"] = "Aluneth", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Magier\nAnlegen: Gewährt die Fähigkeit 'Mal von Aluneth', die eine Rune auf dem Boden platziert, die nach kurzer Zeit explodiert und massiven Schaden verursacht.\n80 ( 80)\nBenötigt Arkanmagier\n\"Nach vielen Rückschlägen schaffte Aegwynn es endlich, das Wesen an einen verzauberten Großstab zu binden. Die Aufgabe, Aluneth einzugrenzen, war somit vollbracht, doch die Wächterin brauchte noch Jahre, bis sie die Macht wirklich nutzen konnte.\"\nVerkaufspreis:" }
entries[242559] = { ["name"] = "Klingen des gefallenen Prinzen", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Frosttodesritter\n\"Wenn meine Zeit gekommen ist, sollst du König sein.\"\nVerkaufspreis:" }
entries[242560] = { ["name"] = "Klingen des gefallenen Prinzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Frosttodesritter\n\"Ich werde Euch der Gerechtigkeit des Grabes zuführen... und die wahre Bedeutung der Furcht lehren.\"" }
entries[242561] = { ["name"] = "G'Hanir, der Mutterbaum", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wiederherstellungsdruide\n\"Am Anfang gab es eine Quelle der Heilung und des Gleichgewichts, einen Ort, an dem alles Leben ruhen und wiederbelebt werden konnte.\"\nVerkaufspreis:" }
entries[242562] = { ["name"] = "Schlund der Verdammten", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Axt\n4 - 9 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Bluttodesritter\n\"Der Durst des Schlunds ist unstillbar. Wird ihm nicht mit frischen Opfern gedient, wird er nicht zögern, stattdessen von seinem Herrn zu trinken.\"\nVerkaufspreis:" }
entries[242563] = { ["name"] = "Apokalypse", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Unheiligtodesritter\n\"Sie soll Zerstörung und Krieg säen. Hunger und Tod. Sie soll mit Macht locken und dann allem Leben ein Ende setzen.\"\nVerkaufspreis:" }
entries[242564] = { ["name"] = "Reißzähne des Verschlingers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Täuschungsschurke\n\"Der Biss des Hundes ist noch immer präsent, all die Jahre nach seinem Tod. Für ein derart primitives Werkzeug ist es erstaunlich wirksam und geschmeidig.\"\nVerkaufspreis:" }
entries[242565] = { ["name"] = "Reißzähne des Verschlingers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Täuschungsschurke\n\"Azhir manari kirel. Akim manari galar!\"\nVerkaufspreis:" }
entries[242566] = { ["name"] = "Fangklaue", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stangenwaffe\n4 - 9 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Überlebensjäger\n\"Der Adlerspeer. Speer der Wilden Götter. Fangklaue. Diese legendäre Waffe trägt viele Namen und viele Segen.\"\nVerkaufspreis:" }
entries[242567] = { ["name"] = "Schicksalshammer", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Streitkolben\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Verstärkungsschamane\n\"Ein Fremder wird den Hammer erheben und durch ihn wird die Gerechtigkeit walten.\"\nVerkaufspreis:" }
entries[242568] = { ["name"] = "Felo'melorn", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigt Feuermagier\n\"...keine elfischen Waffen. Nicht, wenn sie mit Magie und Hass und einer brennenden Begierde nach Rache neu geschmiedet wurden. Nein, Arthas. Felo'melorn ist stärker als je zuvor. So wie auch ich. - Kael'thas Sonnenwanderer\"\nVerkaufspreis:" }
entries[242569] = { ["name"] = "Ursocs Klauen", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wächterdruide\n\"Ursoc, Bruder des Ursol und Beschützer der Furbolgstämme... Träger der Kraft des Waldes selbst.\"\nVerkaufspreis:" }
entries[242570] = { ["name"] = "Ursocs Klauen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Faustwaffe\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wächterdruide\n\"Azeroth wird Euch brauchen. Wenn Ihr nicht bereit seid, könnte die Welt fallen.\"\nVerkaufspreis:" }
entries[242571] = { ["name"] = "Die Silberne Hand", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Streitkolben\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Heiligpaladin\n\"Tyr antwortete, dass er seine silberne Hand nicht als Zeichen seiner Niederlage ansah. Für ihn war es das Symbol seiner Aufopferung für die Verteidigung von Azeroth und er wollte, dass auch der Rest der Welt dies so sah.\"\nVerkaufspreis:" }
entries[242573] = { ["name"] = "T'uure, Fanal der Naaru", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Heiligpriester\n\"Gesegnet seien die Fackelträger, die Licht ins Dunkel bringen.\"\nVerkaufspreis:" }
entries[242574] = { ["name"] = "Thas'dorah, Erbstück von Haus Windläufer", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nDistanz Bogen\n4 - 6 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Treffsicherheitsjäger\n\"Als er aus dem Sonnenbrunnen zurückgeholt wurde, strahlte der Bogen Macht aus. Talanas empfand große Ehre beim Anblick dieser Gabe. Er nannte die Waffe Thas'dorah: 'Ehre des Waldes'.\"\nVerkaufspreis:" }
entries[242575] = { ["name"] = "Xal'atath, Klinge des Schwarzen Imperiums", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Schattenpriester\n\"Xal'atath hat ihren eigenen Kopf. Ignoriert ihr unerträgliches Flüstern. Glaubt niemals ihren Lügen. Nehmt, was Ihr von ihr braucht, aber denkt immer daran, dass die dunkle Präsenz in der Klinge nicht Eure Verbündete ist.\"\nVerkaufspreis:" }
entries[242576] = { ["name"] = "Kriegsklingen der Aldrachi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigt Rachsuchtdämonenjäger\n\"Seine Kriegsklingen heulten lauter als das Schlachtgetöse und zerrissen jeden, der ihnen nahekam. Jeder Dämon, den Toranaar bezwang, schien ihn mit neuer Lebenskraft und Stärke zu erfüllen. Er war eine Armee in sich selbst.\"" }
entries[242577] = { ["name"] = "Kriegsklingen der Aldrachi", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigt Rachsuchtdämonenjäger\n\"Die Aldrachi waren ein stolzes Volk. Zu stolz, um zu dienen. Millionen von Dämonen starben, bevor die Aldrachi ausgelöscht wurden, und nur Sargeras selbst vollbrachte es, ihren König zu töten.\"" }
entries[242578] = { ["name"] = "Sichel von Elune", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Gleichgewichtsdruide\n\"Hierin steckt eine Kraft, die frei sein will. Durch Gleichgewicht und Beherrschung kann der Wolf gebändigt werden, doch nur für gewisse Zeit.\"\nVerkaufspreis:" }
entries[242579] = { ["name"] = "Fänge von Ashamane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wildheitsdruide\n\"Sie tobte durch die Reihen der Dämonen und verschwand dann zwischen den Bäumen. Sie verbarg sich in den Wipfeln und stürzte sich auf die Kommandanten der Legion. Sie war eine furchterregende Bestie. Sie kannte kein Halten, keine Gnade.\"\nVerkaufspreis:" }
entries[242580] = { ["name"] = "Fänge von Ashamane", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wildheitsdruide\n\"Ashamanes Opfer wird bis heute gedacht. Wir leben durch ihre Gnade und ihre Kinder durchstreifen als treue Begleiter noch immer mit uns die Wälder.\"\nVerkaufspreis:" }
entries[242581] = { ["name"] = "Titanenblitz", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nDistanz Schusswaffe\n3 - 7 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Tierherrschaftsjäger\n\"Ein unnachahmliches Beispiel technomagischer Ingenieurskunst, erfüllt mit der Macht der Stürme.\"\nVerkaufspreis:" }
entries[242582] = { ["name"] = "Schwarzfrost", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigt Frostmagier\n\"Schwarzfrost enthielt nur einen kleinen Teil von Alodis Macht, doch selbst das war mehr, als die meisten Magi je zu beherrschen hoffen durften.\"\nVerkaufspreis:" }
entries[242583] = { ["name"] = "Der Wahrheitshüter", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Schutzpaladin\n\"Als der Hammer das erste Mal fiel, entsprangen Flüsse aus Magma aus dem Eis. Beim zweiten Mal heulte der Himmel auf und Blitze entflammten ihn. Beim dritten Mal drang ein Sonnenstrahl durch den Sturm und flüsterte über die Oberfläche des Wahrheitshüters.\"\nVerkaufspreis:" }
entries[242584] = { ["name"] = "Eidsucher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Schutzpaladin\n\"Töten um des Tötens willen... Erobern um der Eroberung willen... Es liegt keine Ehre in solchen Dingen. Nur Schande und Bedauern.\"\nVerkaufspreis:" }
entries[242585] = { ["name"] = "Zorn des Lichts", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Disziplinpriester\n\"Wir wohnten an diesem Tag voller Hoffnung und Hingabe der Zeremonie bei... und verließen sie voller Kummer.\"\nVerkaufspreis:" }
entries[242586] = { ["name"] = "Die Königsmörder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Meuchelschurke\n\"Es war kein angenehmer Tod. Doch er war schnell, lautlos und effizient. Als der Orc seinen letzten Atemzug tat, verzerrte dies die tödliche Wunde. Niemand konnte sagen, ob er einem Messer, einer Axt oder einem Speer erlegen war.\"\nVerkaufspreis:" }
entries[242587] = { ["name"] = "Die Königsmörder", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Meuchelschurke\n\"Unzählige Stimmen wurden zum Schweigen gebracht, unzählige Anführer gestürzt... alles auf sein launisches, finsteres Geheiß. Für diese Taten würde es keine Wiedergutmachung geben, nur Einsamkeit und Kummer.\"\nVerkaufspreis:" }
entries[242588] = { ["name"] = "Die Schreckensklingen", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Gesetzloser Schurke\n\"Sie sah sich selbst, wie sie eine riesige Piratenflotte kommandierte, eine, die die See beherrschen und ganz Azeroth unterwerfen konnte. Jeder, der es wagte, sie herauszufordern, wurde verbrannt und jede Stadt, die an ihren Schätzen festhielt, vernichtet.\"\nVerkaufspreis:" }
entries[242589] = { ["name"] = "Zorn der Steinmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Streitkolben\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Verstärkungsschamane\n\"Erschaffen durch die Macht des Schicksalshammers und des Schamanen, der diesen trägt.\"\nVerkaufspreis:" }
entries[242591] = { ["name"] = "Sharas'dal, Szepter der Gezeiten", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Streitkolben\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Wiederherstellungsschamane\n\"Sie trieben den Abgrund hinab, doch Azshara und ihre Hochgeborenen blieben ungebrochen. Sie waren von absoluter Dunkelheit umgeben, und die Königin zwang Sharas'dal, ihnen das Licht zu bringen...\"\nVerkaufspreis:" }
entries[242592] = { ["name"] = "Schild der Meereskönigin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Wiederherstellungsschamane\n\"Als der Ozean das Leben aus ihren Körpern schmetterte, regten sich uralte Kreaturen in der Dunkelheit. Ihr Flüstern floss durch die Strömung. Ihre Macht legte sich eng um die Königin und ihre Diener.\"\nVerkaufspreis:" }
entries[242593] = { ["name"] = "Die Faust des Ra-den", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Elementarschamane\n\"Um Al'Akirs Untergang zu besiegeln, donnerte Meister Ra seine Faust in den Gipfel des Berges. Der Himmel brach auf und all das Feuer und der Zorn darin stürzte hinab auf den Windlord.\"\nVerkaufspreis:" }
entries[242594] = { ["name"] = "Schutz des hohen Hüters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigt Elementarschamane\n\"Ra und Helya erschufen einen Schild, den Schutz des hohen Hüters, als Schlüssel für die Elementarebene. Er pulsierte mit der Energie der vier Elemente, die Ra nach Belieben rufen konnte.\"\nVerkaufspreis:" }
entries[242595] = { ["name"] = "Sheilun, Stab der Nebel", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigt Nebelwirkermönch\n\"Ihr sucht die ruhige, unausweichliche Macht eines tiefen Flusses, der Schluchten in den stärksten Stein schneidet und Krieger mit seinen Strömungen ohne das leiseste Kräuseln hinfortträgt. Sheilun ist die Verkörperung dieses Konzepts.\"\nVerkaufspreis:" }
entries[242596] = { ["name"] = "Fu Zan, Gefährte des Wanderers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigt Braumeistermönch\n\"Von Anfang an hat dieser Stab legendäre Wesen und unsterbliche Geister begleitet, während sie wichtige Arbeiten in ganz Azeroth ausführten.\"\nVerkaufspreis:" }
entries[242597] = { ["name"] = "Fäuste der Himmel", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigt Windläufermönch\n\"Als Irmaat seine zwei Waffen erhob und die Macht in ihnen auf die Probe stellte, entsprang daraus unkontrollierbare Wut.\"\nVerkaufspreis:" }
entries[242598] = { ["name"] = "Szepter des Sargeras", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigt Zerstörungshexenmeister\n\"Als schließlich der Moment kam, in dem Ner'zhul zum Handeln gezwungen war, tat er es ganz hemmungslos und dachte dabei nicht an Konsequenzen. Die Vernichtung von Draenor war ihm egal, er hieß sie sogar als Teil seines Vermächtnisses willkommen.\"\nVerkaufspreis:" }
entries[242599] = { ["name"] = "Ulthalesh, Sense der Totenwinde", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigt Gebrechenhexenmeister\n\"Der Meister der Sichel wird entweder Sataiel besiegen oder verschlungen werden, was die Klinge nur noch stärker machen wird. Danach wird ein anderer kommen, um seinen Platz einzunehmen. Und danach wieder ein anderer.\"\nVerkaufspreis:" }
entries[242600] = { ["name"] = "Schädel der Man'ari", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigt Dämonologiehexenmeister\n\"Als Thal'kiel endlich erschien, war er verändert. Um Jahrhunderte gealtert, allein in der Dunkelheit mit seinen Gedanken und Sklaven. Er war buckelig und hatte ein merkwürdiges Glänzen in den Augen. Er beschwor seine Erwecker und wir antworteten ihm...\"\nVerkaufspreis:" }
entries[242601] = { ["name"] = "Fäuste der Himmel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Faustwaffe\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigt Windläufermönch\n\"Es gab einen großen Lichtblitz und einen Windstoß, und dann war es schon getan - Irmaat konnte seine Waffen spüren. Al'burq und Alra'ed bebten mit der Macht der Elemente.\"\nVerkaufspreis:" }
entries[242602] = { ["name"] = "Geheimnisse der Leere", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Schattenpriester\n\"Als ich die Klinge berührte, erklang ein Name in meinem Verstand: Xal'atath. Ich wusste, dass ich den Dolch nicht vernichten konnte. Noch nicht. Wie kann man eine Macht bezwingen, die man nicht versteht?\"\nVerkaufspreis:" }
entries[242603] = { ["name"] = "Herz des Phönix", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigt Feuermagier\n\"Als das Kämpfen ein Ende gefunden hatte, war Dath'Remar mit Dämonenblut bedeckt. Mit Einbruch der Nacht wurde uns klar, dass noch mehr Schlachten bevorstünden. Und dennoch, dieser Elf mit seiner Klinge gab uns Hoffnung, dass der Sieg in Reichweite lag.\"\nVerkaufspreis:" }
entries[242604] = { ["name"] = "Die Schreckensklingen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigt Gesetzloser Schurke\n\"Keine Klinge kann so viel unschuldiges Blut vergießen, ohne auch einen Zoll von ihrem Träger einzufordern. Dies ist kein Schatz.\"\nVerkaufspreis:" }
entries[242605] = { ["name"] = "Rückgrat von Thal'kiel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigt Dämonologiehexenmeister\n\"Die Schreie des Erweckers hallten über Argus. Sie stellen eine düstere Erinnerung an den Preis dar, den er dafür zahlen musste, sich mit Dämonen eingelassen zu haben.\"\nVerkaufspreis:" }
entries[242617] = { ["name"] = "Seltsames Simulakrum", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Untersucht das Simulaktrum und enthüllt seine wahre Natur.\n80 ( 80)\n\"Dies scheint just die Artefaktwaffe zu sein, die Ihr bereits in Händen haltet. Was ist das für ein Zauberwerk?\"" }
entries[242622] = { ["name"] = "Kriegsmeutengebundenes Reinigungspaket", ["text"] = "Veteran\nWird beim Aufheben gebunden\nBenutzen: Schaltet künftige Veteranengegenstände in neuerlebten verstörenden Visionen frei, die bis zum Ausrüsten kriegsmeutengebunden sind.\nSchließt den Erfolg \"Maskierter Monolog (neuerlebt)\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während eine beliebige Gesichtslosenmaske aktiv ist." }
entries[242623] = { ["name"] = "Verzaubertes kriegsmeutengebundenes Reinigungspaket", ["text"] = "Champion\nWird beim Aufheben gebunden\nBenutzen: Schaltet künftige Championgegenstände in neuerlebten verstörenden Visionen frei, die bis zum Ausrüsten kriegsmeutengebunden sind.\nSchließt den Erfolg \"Symphonie der Masken (neuerlebt)\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während mindestens 5 Gesichtslosenmasken aktiv sind." }
entries[242627] = { ["name"] = "Schaurige Klinge der Verlassenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242628] = { ["name"] = "Groteske Klinge der Verlassenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Sie kreischt vor Entzückung, während sie Fleisch und Knochen durchtrennt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242629] = { ["name"] = "Klinge der heulenden Banshee", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Keine von diesem Schwert geschlagene Wunde heilt je wirklich.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242630] = { ["name"] = "Krankhafte Klinge der Verlassenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242631] = { ["name"] = "Schaurige Großklinge der Verlassenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[242632] = { ["name"] = "Groteskes Großschwert der Verlassenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n\"Jeder Körper, den es unter die Erde bringt, wird Nährboden für die Seuche.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
