entries[242706] = { ["name"] = "Kuriose Kuriosität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n80 ( 80)\n\"Den ewigen Drachenschwarm könnte das vielleicht interessieren.\"" }
entries[242711] = { ["name"] = "Streng riechender Trüffel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen (Realzeit)\nBenutzen: Verwandelt Euch in einen Sporling." }
entries[242713] = { ["name"] = "Prächtiger K'arroc", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein fleischgewordenes technologisches Wunder. Dieser K'arroc repräsentiert die Hoffnung auf ein besseres K'aresh.\"\nWeltquest:\nDie Hoffnung von K'aresh\nZone:\nK'aresh" }
entries[242714] = { ["name"] = "Umbralk'arroc", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein wilder K'arroc, der besonders gut darauf ausgelegt ist, das ewigwährende Zwielicht von K'aresh zu durchstreifen.\"\nErfolg:\nRuhm des Omegaschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[242715] = { ["name"] = "K'arrocflinkschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk für geleistete Dienste. Dieser K'arroc hat schon einige gefährliche Flüge hinter sich.\"\nQuest:\nAuf nach Tazavesh, wieder einmal\nZone:\nK'aresh" }
entries[242717] = { ["name"] = "Lavendelblauer K'arroc", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der vorherige Halter dieses besonders streitlustigen K'arroc starb während einer Untersuchung des ungebundenen Raums. Vielleicht akzeptiert er ja Euch... Oder vielleicht auch nicht.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n10" }
entries[242728] = { ["name"] = "Der Knochengefrierer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Kriecher ist ein erbitterter Rivale des Knochenschmelzers und wurde nach einer vernichtenden Niederlage aus seinem Versteck in der Manaschmiede Omega vertrieben. Jetzt will er von demjenigen lernen, der seinen größten Feind entthront hat.\"\nFraktion:\nVandalen der Manaschmiede\nRuhmstufe:\n14\nOrt:\nSchattenpunkt" }
entries[242729] = { ["name"] = "Rubinroter Leerenkrabbler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 15 beim Bund von K'aresh.\n\n\"Dieser Leerenkrabbler wurde vom Bund von K'aresh für Forschungszwecke \"gerettet\". Er hat sich als überaus robustes Reittier erwiesen.\"\nVerkäufer:\nOm'sirik\nZone:\nK'aresh\nKosten:\n8.125" }
entries[242730] = { ["name"] = "Ätzender Leerenkrabbler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Krabbler hat sich an giftigen Dünsten gelabt, wodurch sein Körper mit mächtigen Säuren angereichert wurde.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n7" }
entries[242733] = { ["name"] = "Blauer Ingmar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eine besonders seltene Variante der Schieferrücken. Der \"Blaue Ingmar\" wurde zuvor beim Transport von Lasten eingesetzt.\"\nQuest:\nEuer Blauer\nZone:\nK'aresh" }
entries[242734] = { ["name"] = "Neugieriger Schieferrücken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser neugierige Schieferrücken hat es irgendwie geschafft, in einer Kiste steckenzubleiben. Wie er es da überhaupt reingeschafft hat, ist noch nicht geklärt.\"\nBeute:\nZuckende Kiste des Gipfels\nZone:\nK'aresh" }
