entries[243013] = { ["name"] = "Verdammnisfeuerdynamo", ["text"] = "Dämonenrelikt\nWird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Sturmrufer '.\n\nSturmrufer\nIhr könnt Zauber aus der Bewegung heraus wirken.\n\nBewegung erzeugt 6 Sek. lang elektrische Energie um Euch herum, die regelmäßig Blitzschläge beschwört, die Gegnern in der Nähe [(130% Angriffs-/Zaubermacht)] Schaden zufügen.\n80 ( 80)" }
