entries[243018] = { ["name"] = "Versteinerter Zweig von Fennad", ["text"] = "\"Nicht mal groß genug für einen Zauberstab.\"\nVerkaufspreis:" }
entries[243019] = { ["name"] = "Leerenschwingendrachenfalke", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er schweift mit lautlosen Flügeln durch den Himmel, während in seinen Augen das Echo vergessener Sterne glüht.\"\nPromotion" }
entries[243020] = { ["name"] = "Lichtschwingendrachenfalke", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er strahlt Wärme und Anmut aus, getragen von Flügeln aus Licht.\"\nPromotion" }
