entries[243031] = { ["name"] = "Mrrmgmrl Grmmlmglrg", ["text"] = "Frostrelikt\nWird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Schrecken aus der Tiefe '.\n\nSchrecken aus der Tiefe\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu.\n80 ( 80)" }
entries[243032] = { ["name"] = "Fehlerhafter Zorn der Gezeiten", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Berührung der Bosheit '.\n\nBerührung der Bosheit\nEure Schaden verursachenden Zauber und Fähigkeiten sowie die Eurer Diener belegen Gegner regelmäßig mit ' Teufelsberührt '. Der durch ' Verdrehter Kreuzzug ' beschworene höllische Schreckenslord trifft mit ' Teufelsberührt ' belegte Gegner immer kritisch.\n\nTeufelsberührt\nAlle 4 Sek. explodiert das Ziel und fügt Gegnern in der Nähe 3% des in den letzten 4 Sek. erlittenen Schadens zu.\n\nFügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n80 ( 80)" }
entries[243033] = { ["name"] = "Fehlerhafter Gesplitterter Komet", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Schrecken aus der Tiefe '.\n\nSchrecken aus der Tiefe\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu.\n80 ( 80)" }
entries[243034] = { ["name"] = "Fehlerhafter Gelmoggs geborstener Schädel", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Seelenstärke des Hochbergs '.\n\nSeelenstärke des Hochbergs\nAlle 12 Sek. sammelt Ihr 3% von sämtlichem erlittenen Schaden als ' Seelenstärke ' an. Nach 8 Sek. wird ' Seelenstärke ' zu einer Schutzbarriere, die 4 Sek. lang Schaden in der angesammelten Höhe absorbiert.\n80 ( 80)" }
entries[243035] = { ["name"] = "Fehlerhaftes Ettinknochenfragment", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Seelen des Krächzens '.\n\nSeelen des Krächzens\nEure Zauber und Fähigkeiten haben eine Chance, einen Schwarm Geisteradler zu beschwören, die auf Gegner in der Nähe herabstürzen und bei Aufprall explodieren. Explosionen heilen Verbündete und fügen Gegnern innerhalb von 5 Metern [[2 * (368% Angriffs-/Zaubermacht)]][[(368% Angriffs-/Zaubermacht)]] Naturschaden zu.\n80 ( 80)" }
entries[243036] = { ["name"] = "Fehlerhafter Schimmernder Eisendorn", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Arkane Aegis '.\n\nArkane Aegis\nIhr kanalisiert bei Rückwärtsbewegung ' Arkane Aegis ', absorbiert bis zu [(2100% Angriffs-/Zaubermacht)] Schaden und verringert Eure Bewegungsgeschwindigkeit um 80%. Wenn Ihr ' Arkane Aegis ' nicht kanalisiert, regeneriert sie sich um 5% pro Sekunde. Wird die ' Arkane Aegis ' zerschlagen, ist sie 30 Sek. lang unbenutzbar.\n80 ( 80)" }
entries[243037] = { ["name"] = "Fehlerhafte Xakals Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Temporalgegenschlag '.\n\nTemporalgegenschlag\nWenn Ihr Schaden absorbiert, fügt Ihr dem Angreifer [(31% Angriffs-/Zaubermacht)] Arkanschaden zu und verringert sein Angriffstempo 3 Sek. lang um 20%.\n80 ( 80)" }
